        return map;
    }

    static Map<String, Object> release(int revisionNo, String releaseBatchId, String releasedBy,
                                       java.time.Instant releasedAt, List<Measurement> released,
                                       BatchStatistics stats) {
        Map<String, Object> map = ordered();
